using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.Tests.cluster
{
    public class ReplicaSyncSessionTests
    {
        [Fact]
        public async Task SendCheckpointAsync_LogsAcquireCheckpointEntryIteration()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();
            var mockStoreWrapper = new Mock<StoreWrapper>(null, null);
            var mockClusterProvider = new Mock<ClusterProvider>(null);

            // Setup clusterProvider to return dummy values for GetReplicationLogCheckpointManager and clusterManager.CurrentConfig
            mockClusterProvider.Setup(cp => cp.GetReplicationLogCheckpointManager(It.IsAny<StoreType>())).Returns((object)null);
            var mockClusterManager = new Mock<dynamic>();
            mockClusterManager.Setup(cm => cm.CurrentConfig).Returns(new
            {
                GetWorkerAddressFromNodeId = (System.Func<string, (string, int)>)(id => ("127.0.0.1", 12345))
            });
            mockClusterProvider.SetupGet(cp => cp.clusterManager).Returns(mockClusterManager.Object);

            // Setup replicaCheckpointEntry with dummy metadata
            var dummyMetadata = new
            {
                storeVersion = 1L,
                objectStoreVersion = 1L
            };
            var dummyCheckpointEntry = new
            {
                metadata = dummyMetadata
            };

            // Create ReplicaSyncSession instance via reflection since constructor is internal
            var sessionType = typeof(ReplicaSyncSession);
            var ctor = sessionType.GetConstructors(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)[0];
            var session = (ReplicaSyncSession)ctor.Invoke(new object[]
            {
                mockStoreWrapper.Object,
                mockClusterProvider.Object,
                null, // replicaSyncMetadata
                default, // CancellationToken
                "replicaNodeId",
                null, // replicaAssignedPrimaryId
                null, // replicaCheckpointEntry
                0L,
                0L,
                mockLogger.Object
            });

            // Act
            await session.SendCheckpointAsync();

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("AcquireCheckpointEntry iteration")),
                    null,
                    It.IsAny<Func<It.IsAnyType, System.Exception, string>>()),
                Times.AtLeastOnce);
        }
    }
}
